import {trainingOptions,MAX_TRAINING_RANK} from './expedition-data.mjs';
import {isAdvanced} from './expedition-growth.mjs';
export function trainingPlanView(member,quote,pending,open=false,active=true){
 return `<details class="training-plan" ${open?'open':''}><summary>规划培养调整 · ${quote.rows.length}项变化</summary><p>先列出目标等级，再一次应用。退回经验可用于同一草案中的其他训练；普通课程、后期进阶和战术保留。</p><div class="training-plan-options">${Object.entries(trainingOptions(member.id)).filter(([,o])=>!isAdvanced(o.id)||member.unlocked.includes(o.id)).map(([key,o])=>`<label>${o.name}<select data-training-target="${key}" ${pending?'disabled':''}>${Array.from({length:MAX_TRAINING_RANK+1},(_,n)=>`<option value="${n}" ${(quote.target[key]||0)===n?'selected':''}>目标 +${n}${(member.training[key]||0)===n?' · 当前':''}</option>`).join('')}</select></label>`).join('')}</div><p class="training-plan-totals" role="status">退回 <b data-plan-value="refund">${quote.refund}</b>经验 · 花费 <b data-plan-value="cost">${quote.cost}</b>经验<br>可用 <span data-plan-value="before">${quote.availableBefore}</span> → <strong data-plan-value="after">${quote.availableAfter??'不可应用'}</strong>经验 · 累计仍为 ${quote.earned}</p>${quote.rows.length?`<ul>${quote.rows.map(r=>`<li>${r.name} +${r.before} → +${r.after}（${r.refund?'退回'+r.refund:'花费'+r.cost}经验）</li>`).join('')}</ul>`:''}${pending?'<p class="ready-diff">请先领取远征结算，草案不会改变待结算资产。</p>':''}${quote.reasons.length?`<p class="ready-diff">${quote.reasons.join('；')}</p>`:''}<button data-plan-action="rehearse" ${pending||!quote.allowed||!active?'disabled':''}>试演当前与草案</button>${!active?'<p>该队员当前未出战，先安排出战后可试演；培养草案仍可应用。</p>':''}<button data-plan-action="apply" ${pending||!quote.allowed?'disabled':''}>应用培养草案</button><button data-plan-action="restart">按当前培养重新开始</button></details>`;
}
